<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('leads.manage');
$id=max(0,(int)($_GET['id']??$_POST['id']??0));$row=null;if($id){$s=db()->prepare('SELECT * FROM lead_campaigns WHERE id=?');$s->execute([$id]);$row=$s->fetch();if(!$row){http_response_code(404);exit('Campaña no encontrada.');}}$pageTitle=$row?'Editar campaña de leads':'Nueva campaña de leads';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$channel=trim((string)($_POST['channel']??'website'));$objective=trim((string)($_POST['objective']??''));$budget=max(0,(float)($_POST['budget']??0));$currency=(string)($_POST['currency']??'USD');$start=($_POST['start_date']??'')?:null;$end=($_POST['end_date']??'')?:null;$status=(string)($_POST['status']??'draft');$notes=trim((string)($_POST['notes']??''));if($name==='')$errors[]='El nombre es obligatorio.';if(!in_array($currency,['CLP','USD','BRL'],true))$currency='USD';if(!in_array($status,['draft','active','paused','completed'],true))$status='draft';if(!$errors){if($id)db()->prepare('UPDATE lead_campaigns SET name=?,channel=?,objective=?,budget=?,currency=?,start_date=?,end_date=?,status=?,notes=? WHERE id=?')->execute([$name,$channel,$objective,$budget,$currency,$start,$end,$status,$notes,$id]);else{db()->prepare('INSERT INTO lead_campaigns(name,channel,objective,budget,currency,start_date,end_date,status,notes,created_by) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$name,$channel,$objective,$budget,$currency,$start,$end,$status,$notes,(int)$_SESSION['user_id']]);$id=(int)db()->lastInsertId();}flash('success','Campaña guardada.');redirect('lead_campaigns.php');}}
$v=fn($k,$d='')=>$_POST[$k]??($row[$k]??$d);require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><h2>Información de campaña</h2><a class="btn btn-light" href="lead_campaigns.php">Cancelar</a></div><div class="panel-body form-grid three"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label class="span-2">Nombre *<input name="name" required value="<?=e($v('name'))?>"></label><label>Canal<select name="channel"><?php foreach(['website'=>'Sitio web','email'=>'Email','social'=>'Redes sociales','ads'=>'Publicidad','event'=>'Evento','referral'=>'Referidos','other'=>'Otro']as$k=>$l):?><option value="<?=$k?>" <?=$v('channel','website')===$k?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label class="full">Objetivo<input name="objective" value="<?=e($v('objective'))?>" placeholder="Ej: captar empresas interesadas en rediseño web"></label><label>Presupuesto<input type="number" step="0.01" min="0" name="budget" value="<?=e($v('budget',0))?>"></label><label>Moneda<select name="currency"><?php foreach(['CLP','USD','BRL']as$c):?><option <?=$v('currency','USD')===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select></label><label>Estado<select name="status"><?php foreach(['draft'=>'Borrador','active'=>'Activa','paused'=>'Pausada','completed'=>'Finalizada']as$k=>$l):?><option value="<?=$k?>" <?=$v('status','draft')===$k?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Inicio<input type="date" name="start_date" value="<?=e($v('start_date'))?>"></label><label>Fin<input type="date" name="end_date" value="<?=e($v('end_date'))?>"></label><label class="full">Notas<textarea name="notes"><?=e($v('notes'))?></textarea></label><div class="full form-actions"><button class="btn btn-primary">GUARDAR</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
